-- GF2 eye-glow: glowing iris for gf2_soppo. [AUTO-GENERATED by build.py from
-- GF2_AIO_source/shaders/models_eyeglow.s -- edit the template, not this file]
-- Put on the character's eye surface by gf2_aio.script while her light is on.
-- Same as models\selflight, except the glow pass uses accum_gf2_soppo_eyeglow.ps
-- (color/brightness come from her gf2_eyeglow LTX).

function normal		(shader, t_base, t_second, t_detail)
	shader	: begin		("deffer_model_flat", "deffer_base_flat")
			: fog		(false)
			: emissive 	(true)

	shader:dx10texture("s_base", t_base)
	shader:dx10sampler("smp_base")
	shader:dx10stencil(true, cmp_func.always, 255 , 127, stencil_op.keep, stencil_op.replace, stencil_op.keep)
	shader:dx10stencil_ref(1)
end

function l_special	(shader, t_base, t_second, t_detail)
	shader	: begin		("deffer_model_flat", "accum_gf2_soppo_eyeglow")
			: zb 		(true,false)
			: fog		(false)
			: emissive 	(true)

	shader:dx10texture("s_base", t_base)
	shader:dx10sampler("smp_base")
end
